package com.hs.listing.model; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="listing_office_operating_hours") @Getter @Setter @NoArgsConstructor public class ListingOfficeOperatingHour { @Id @Column(length=36) private String id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="listing_id") private ListingOfficeDetail listing; @Enumerated(EnumType.STRING) @Column(name="day_of_week",nullable=false) private DayOfWeek dayOfWeek; @Column(name="open_time",nullable=false) private LocalTime openTime; @Column(name="close_time",nullable=false) private LocalTime closeTime; @PrePersist void pre(){if(id==null)id=UUID.randomUUID().toString();} }
